import {esc,icon} from './ui.mjs';

const statusLabels={loading:'正在核对商品',unpublished:'尚未上架',unavailable:'暂不可购买',failed:'商品信息暂未取得'};
const statusHints={loading:'正在核对商品开放状态与有效期。',unpublished:'套餐尚未上架，有效期与服务开放状态待配置。',unavailable:'当前商品暂不可购买，请等待服务与权益配置完成。',failed:'商品信息暂未取得；所列为方案价，请在详情页再次核对。'};
const tone=plan=>/^[a-z][a-z0-9-]{0,63}$/.test(plan?.id)?plan.id:'custom';
const extraAttributes=attributes=>Object.entries(attributes).filter(([key])=>/^data-[a-z][a-z0-9-]*$/.test(key)).map(([key,value])=>` ${key}="${esc(value)}"`).join('');
const shortMoney=cents=>(cents/100).toFixed(2).replace(/\.00$/,'').replace(/(\.\d)0$/,'$1');

// All bundle families use this single cover / price / services / action layout.
export function bundlePreviewCard(plan,{state=null,attributes={}}={}){
 const id=tone(plan),sku='bundle-'+id,tracked=Object.hasOwn(statusLabels,state),featured=Boolean(plan.featured),features=Array.isArray(plan.features)?plan.features:[];
 const hasReferencePrice=Number.isSafeInteger(plan.priceCents)&&plan.priceCents>0&&plan.priceCents<=10000000;
 const price=hasReferencePrice?'<small>¥</small>'+shortMoney(plan.priceCents):'待发布';
 const priceUnit=hasReferencePrice?tracked||!plan.durationDays?'方案价 / 套 · 未上架':`建议价 / ${plan.durationDays} 天 · 未上架`:'服务与售价待确认';
 return `<article class="purchase-plan commerce-center-plan commerce-center-plan-bundle commerce-center-plan-${id} ${featured?'featured':''}"${extraAttributes(attributes)}><div class="commerce-center-plan-cover"><div class="commerce-center-plan-decoration" aria-hidden="true">${icon('grid',88)}</div><div class="purchase-plan-top"><span class="purchase-plan-icon">${icon('grid',24)}</span><span class="purchase-status"${tracked?` data-revision-bundle-state="${state}"`:''}>${tracked?statusLabels[state]:'组合方案'}</span></div><h3>${esc(plan.name)}</h3><p class="commerce-center-audience">${esc(plan.audience||plan.description||'按研究阶段组合服务')}</p><div class="purchase-price"><b>${price}</b><span>${priceUnit}</span></div></div><div class="commerce-center-plan-body"><div class="commerce-center-feature-label">${tracked?'套餐服务清单':'一套包含这些服务'}<span>${plan.totalUses?esc(plan.totalUses)+' 次总额度':features.length+' 项'}</span></div><ul>${features.map(feature=>`<li><span aria-hidden="true">${icon('clock',14)}</span>${esc(String(feature).replace(/^规划：/,''))}</li>`).join('')}</ul>${tracked?`<p class="commerce-member-description">${statusHints[state]}</p>`:''}<a class="btn secondary full" data-commerce-offer="bundle:${esc(sku)}" href="#membership/checkout?kind=bundle&plan=${encodeURIComponent(id)}&quantity=1">查看套餐详情 ${icon('arrow',16)}</a><small class="commerce-center-plan-footnote">${hasReferencePrice&&plan.durationDays?'各服务次数独立使用 · 不自动续费':'尚未上架 · 确认规则后开放购买'}</small></div></article>`;
}

export function publishedBundleCard(product,plan,{attributes={}}={}){
 const id=tone(plan),tracked=Object.hasOwn(attributes,'data-revision-bundle'),featured=Boolean(plan.featured),price=(product.priceCents/100).toFixed(2).replace(/\.00$/,'');
 return `<article class="purchase-plan commerce-center-plan commerce-center-plan-bundle commerce-center-plan-live commerce-center-plan-${id} ${featured?'featured':''}" data-bundle-product="${esc(product.id)}"${extraAttributes(attributes)}><div class="commerce-center-plan-cover"><div class="commerce-center-plan-decoration" aria-hidden="true">${icon('grid',88)}</div><div class="purchase-plan-top"><span class="purchase-plan-icon">${icon('grid',24)}</span><span class="purchase-status"${tracked?' data-revision-bundle-state="published"':''}>已上架</span></div><h3>${esc(product.title)}</h3><p class="commerce-center-audience">套餐有效期 ${product.durationDays} 天</p><div class="purchase-price"><b><small>¥</small>${price}</b><span>人民币 / 套</span></div></div><div class="commerce-center-plan-body"><div class="commerce-center-feature-label">一套包含这些服务<span>${product.bundleItems.length} 项</span></div><ul>${product.bundleItems.map(item=>`<li><span aria-hidden="true">${icon('check',14)}</span>${esc(item.title)} × ${item.quantity}</li>`).join('')}</ul><p class="commerce-member-description">${esc(product.description)}</p><a class="btn ${featured?'primary':'secondary'} full" data-commerce-offer="bundle:${esc(product.id)}"${tracked?` data-revision-bundle-checkout="${esc(product.id)}"`:''} href="#membership/pay?product=${encodeURIComponent(product.id)}">确认购买 ${icon('arrow',16)}</a><small class="commerce-center-plan-footnote">次数按服务分别使用 · 不与充值积分互换</small></div></article>`;
}
